'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const deferred = () => {
  let resolve, reject;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
};

async function main() {
  // 1. Rejected load is never cached; subsequent get retries.
  {
    let calls = 0;
    const cache = createCache({ now: () => 0, load: () => (++calls === 1 ? Promise.reject('boom') : 'ok') });
    await assert.rejects(cache.get('k'), r => r === 'boom');
    assert.equal(await cache.get('k'), 'ok');
    assert.equal(calls, 2);
  }
  // 2. Synchronous throw from load: same rejection to all waiters, retry works.
  {
    let calls = 0;
    const cache = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw new Error('sync'); return 7; } });
    const a = cache.get('k');
    const b = cache.get('k');
    await assert.rejects(a, /sync/);
    await assert.rejects(b, /sync/);
    assert.equal(calls, 1); // deduped flight
    assert.equal(await cache.get('k'), 7);
  }
  // 3. set() wins over a pending load; late completion must not overwrite or restart TTL.
  {
    const gate = deferred();
    let t = 0;
    let calls = 0;
    const cache = createCache({ now: () => t, ttlMs: 100, load: () => { calls++; return gate.promise; } });
    const reader = cache.get('k');
    await tick();
    cache.set('k', 'manual');
    t = 50;
    gate.resolve('loaded');
    assert.equal(await reader, 'loaded'); // original waiter still gets its value
    t = 150; // beyond manual TTL (0+100); loaded commit would have deadline 150+100
    assert.equal(await cache.get('k'), await cache.get('k')); // expired -> reload (gate already resolved -> 'loaded')
    assert.equal(calls, 2);
  }
  // 4. Obsolete flight must not detach a newer flight (registry clobber).
  {
    const g1 = deferred();
    const g2 = deferred();
    let calls = 0;
    const cache = createCache({
      now: () => 0,
      load: () => (++calls === 1 ? g1.promise : g2.promise)
    });
    const r1 = cache.get('k');
    await tick();
    cache.invalidate('k');
    const r2 = cache.get('k'); // joins flight 2
    await tick();
    const r3 = cache.get('k'); // must join flight 2 as well
    assert.equal(calls, 2);
    g1.resolve('old'); // obsolete flight settles first
    assert.equal(await r1, 'old');
    await tick();
    g2.resolve('new');
    assert.equal(await r2, 'new');
    assert.equal(await r3, 'new');
    assert.equal(calls, 2); // r3 shared flight 2; obsolete settle didn't detach it
    assert.equal(await cache.get('k'), 'new'); // committed by flight 2
  }
  // 5. Double invalidate: separate barriers, even with no stored value.
  {
    const gates = [deferred(), deferred(), deferred()];
    let calls = 0;
    const cache = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const r1 = cache.get('k');
    await tick();
    cache.invalidate('k');
    const r2 = cache.get('k');
    await tick();
    cache.invalidate('k');
    const r3 = cache.get('k');
    await tick();
    assert.equal(calls, 3);
    gates[0].resolve('a'); gates[1].resolve('b'); gates[2].resolve('c');
    assert.equal(await r1, 'a');
    assert.equal(await r2, 'b');
    assert.equal(await r3, 'c');
    assert.equal(await cache.get('k'), 'c');
  }
  // 6. clear() detaches all flights; stale values never resurrect.
  {
    const gate = deferred();
    const cache = createCache({ now: () => 0, load: k => gate.promise.then(() => 'stale-' + k) });
    const r1 = cache.get('x');
    const r2 = cache.get('y');
    await tick();
    cache.clear();
    gate.resolve();
    assert.equal(await r1, 'stale-x');
    assert.equal(await r2, 'stale-y');
    assert.equal(cache.size, 0); // nothing committed
  }
  // 7. ttlMs = 0: dedupes unsettled flight, never reuses settled value.
  {
    let calls = 0;
    const gate = deferred();
    const cache = createCache({ now: () => 0, ttlMs: 0, load: () => (++calls === 1 ? gate.promise : 'v' + calls) });
    const a = cache.get('k');
    const b = cache.get('k');
    assert.equal(calls, 1);
    gate.resolve('first');
    assert.equal(await a, 'first');
    assert.equal(await b, 'first');
