    assert.equal(calls, 2);
  }
  // 4. Obsolete flight must not detach a newer flight (registry clobber).
  {
    const g1 = deferred();
    const g2 = deferred();
    let calls = 0;
    const cache = createCache({
      now: () => 0,
      load: () => (++calls === 1 ? g1.promise : g2.promise)
    });
    const r1 = cache.get('k');
    await tick();
    cache.invalidate('k');
    const r2 = cache.get('k'); // joins flight 2
    await tick();
    const r3 = cache.get('k'); // must join flight 2 as well
    assert.equal(calls, 2);
    g1.resolve('old'); // obsolete flight settles first
    assert.equal(await r1, 'old');
    await tick();
    g2.resolve('new');
    assert.equal(await r2, 'new');
    assert.equal(await r3, 'new');
    assert.equal(calls, 2); // r3 shared flight 2; obsolete settle didn't detach it
    assert.equal(await cache.get('k'), 'new'); // committed by flight 2
  }
  // 5. Double invalidate: separate barriers, even with no stored value.
  {
    const gates = [deferred(), deferred(), deferred()];
    let calls = 0;
    const cache = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const r1 = cache.get('k');
    await tick();
    cache.invalidate('k');
    const r2 = cache.get('k');
    await tick();
    cache.invalidate('k');
    const r3 = cache.get('k');
    await tick();
    assert.equal(calls, 3);
    gates[0].resolve('a'); gates[1].resolve('b'); gates[2].resolve('c');
    assert.equal(await r1, 'a');
    assert.equal(await r2, 'b');
    assert.equal(await r3, 'c');
    assert.equal(await cache.get('k'), 'c');
  }
  // 6. clear() detaches all flights; stale values never resurrect.
  {
    const gate = deferred();
    const cache = createCache({ now: () => 0, load: k => gate.promise.then(() => 'stale-' + k) });
    const r1 = cache.get('x');
    const r2 = cache.get('y');
    await tick();
    cache.clear();
    gate.resolve();
    assert.equal(await r1, 'stale-x');
    assert.equal(await r2, 'stale-y');
    assert.equal(cache.size, 0); // nothing committed
  }
  // 7. ttlMs = 0: dedupes unsettled flight, never reuses settled value.
  {
    let calls = 0;
    const gate = deferred();
    const cache = createCache({ now: () => 0, ttlMs: 0, load: () => (++calls === 1 ? gate.promise : 'v' + calls) });
    const a = cache.get('k');
    const b = cache.get('k');
    await tick(); // load is invoked on a microtask
    assert.equal(calls, 1);
    gate.resolve('first');
    assert.equal(await a, 'first');
    assert.equal(await b, 'first');
    assert.equal(await cache.get('k'), 'v2');
  }
  // 8. TTL starts at commit, not at get start.
  {
    let t = 0;
    const gate = deferred();
    const cache = createCache({ now: () => t, ttlMs: 100, load: () => gate.promise });
    const r = cache.get('k');
    t = 90; // load takes 90ms
    await tick();
    gate.resolve('v');
    assert.equal(await r, 'v');
    t = 150; // 60ms after commit -> still fresh
    assert.equal(await cache.get('k'), 'v');
  }
  // 9. load synchronously calling set on its own key: set wins.
  {
    const cache = createCache({
      now: () => 0,
      load: () => { cache.set('k', 'from-set'); return 'from-load'; }
    });
    assert.equal(await cache.get('k'), 'from-load'); // waiter gets flight value
    assert.equal(await cache.get('k'), 'from-set');  // stored value is the set one
  }
  // 10. load reads its own key without awaiting -> joins existing flight.
  {
    let calls = 0;
    let joined;
    const cache = createCache({
      now: () => 0,
      load: k => { calls++; joined = cache.get(k); return 'v'; }
    });
    const r = cache.get('k');
    assert.equal(await r, 'v');
    assert.equal(await joined, 'v');
    assert.equal(calls, 1);
  }
  // 11. Rejection of an obsolete (detached) flight doesn't clobber a newer flight.
  {
    const g1 = deferred();
    let calls = 0;
    const cache = createCache({ now: () => 0, load: () => (++calls === 1 ? g1.promise : 'fresh') });
    const r1 = cache.get('k');
    await tick();
    cache.invalidate('k');
    const r2 = cache.get('k');
    await tick();
    g1.reject('old-fail');
    await assert.rejects(r1, r => r === 'old-fail');
    assert.equal(await r2, 'fresh');
    assert.equal(await cache.get('k'), 'fresh');
  }
  console.log('all scratch checks passed');
}

main().catch(err => { console.error(err); process.exit(1); });

