'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      const existing = pending.get(key);
      if (existing !== undefined) return existing;
      // Only the flight currently registered for the key may remove itself
      // and commit. A detached (obsolete) flight still settles its original
      // waiters but must neither store a value nor detach a newer flight.
      const promise = Promise.resolve().then(work).then(
        value => {
          if (pending.get(key) === promise) {
            pending.delete(key);
            commit(value);
          }
          return value;
        },
        reason => {
          if (pending.get(key) === promise) pending.delete(key);
          throw reason;
        }
      );
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };
